public boolean validateWrite()
{
    boolean ret;

    ret = super();

    ret = this.validateContractDates() && ret;
    ret = this.validateProbationDates() && ret;

    return ret;
}

private boolean validateContractDates()
{
    if (this.StartDate > this.EndDate)
    {
        return checkFailed("Contract end date cannot be earlier than the contract start date.");

    }
    return true;
}

private boolean validateProbationDates()
{
    if (this.ProbationStartDate > this.ProbationEndDate)
    {
        return checkFailed("Probation end date cannot be earlier than the probation start date.");

    }
    return true;
}

public void initValue()
{
    super();

    this.LegalEntityDataAreaId = curExt();
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(NVHcmWorkerContractDetails, StartDate):
            this.ProbationStartDate = this.StartDate;
        case fieldNum(NVHcmWorkerContractDetails, ProbationStartDate):
            this.ProbationEndDate = DateTimeUtil::date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(this.ProbationStartDate, 0), HRMParameters::findByCompany(this.LegalEntityDataAreaId).NVWorkerProbationMonthEnd));
        case fieldNum(NVHcmWorkerContractDetails, ProbationEndDate):
            this.updateProbationEndDate();
            break;
    }
}

private void updateProbationEndDate()
{
    NVHcmWorkerContractDetails contractDetails;
    select firstonly maxof(ProbationEndDate) from contractDetails
        where contractDetails.Worker    == this.Worker
        && contractDetails.LegalEntityDataAreaId == this.LegalEntityDataAreaId;
    TransDate probationEndDate = contractDetails.ProbationEndDate;
    if(probationEndDate < this.ProbationEndDate)
        probationEndDate = this.ProbationEndDate;

    HcmEmployment employment;
    HcmEmploymentEmployee employmentEmployee;
    utcdatetime now = DateTimeUtil::utcNow();

    select ValidTimeState(now) employmentEmployee
        order by ValidFrom desc
        exists join employment
            order by ValidTo desc
        where employment.RecId == employmentEmployee.Employment
            && employment.Worker == this.Worker
            && employment.LegalEntity == CompanyInfo::findDataArea(this.LegalEntityDataAreaId).RecId;

    if(employmentEmployee)
    {
        ttsbegin;
        employmentEmployee.selectForUpdate(true);
        employmentEmployee.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
        employmentEmployee.ProbationEndDate = probationEndDate;
        employmentEmployee.update();
        ttscommit;
    }
    else
    {
        select ValidTimeState(now) employment
            order by ValidTo desc
        where employment.Worker == this.Worker
            && employment.LegalEntity == CompanyInfo::findDataArea(this.LegalEntityDataAreaId).RecId;

        if(employment)
        {
            employmentEmployee.validTimeStateUpdateMode(ValidTimeStateUpdate::CreateNewTimePeriod);
            employmentEmployee.ValidFrom        = employment.ValidFrom;
            employmentEmployee.ValidTo          = employment.ValidTo;
            employmentEmployee.Employment       = employment.RecId;
            employmentEmployee.ProbationEndDate = probationEndDate;
            employmentEmployee.insert();
        }
    }
}
